    /// <summary>Where a motif sits on the ring (fixed points of the circle, ring centre radius).</summary>
    public enum FrameSlot { Top, Bottom, TopLeft, TopRight, BottomLeft, BottomRight }

    /// <summary>How the ring itself is dressed beyond its two colours (all drawn from UI_Frame_Ring and plain shapes).</summary>
    public enum FrameRingStyle
    {
        /// <summary>One ring (ring colour) over a rim copy (rim colour, scaled 1.06 behind).</summary>
        Plain,
        /// <summary>A second thinner ring inside (StyleColors[0]).</summary>
        Double,
        /// <summary>Count pearls on the ring centre line; StyleColors cycle (day_by_day: the last colour every 7th pearl).</summary>
        Pearls,
        /// <summary>The ring cut into Count equal bands, one per StyleColors entry.</summary>
        Bands,
        /// <summary>The ring colour at the top fading to StyleColors[0] at the bottom.</summary>
        Gradient,
        /// <summary>A dotted line (StyleColors[0]) inside the ring.</summary>
        Dotted,
        /// <summary>Fine graduations (StyleColors[0]) around the ring.</summary>
        Ticks,
        /// <summary>Thin lines (StyleColors[0]) joining the motifs in slot order.</summary>
        Lines,
    }

    /// <summary>One motif on a frame: sprite file name (Art/UI/Profile/Frames/M_&lt;Sprite&gt;.png), slot and tint (white = own colours).</summary>
    public readonly struct FrameMotif
    {
        public readonly string Sprite;
        public readonly FrameSlot Slot;
        public readonly Color32 Tint;

        public FrameMotif(string sprite, FrameSlot slot, uint rgb)
        {
            Sprite = sprite;
            Slot = slot;
            Tint = new Color32((byte)(rgb >> 16), (byte)(rgb >> 8), (byte)rgb, 255);
        }
    }

    /// <summary>The art of one profile frame (ids follow frame.&lt;name&gt; of the doc). Generated by SourceArt/UI/Tools/pw_ui_sprites_t44b.py:
    /// do not edit by hand, change FRAMES in the script and run it again.
    /// Layout: UI_Frame_Ring (512 px, ring band between radius 204 and 246) tinted RingColor; a copy scaled 1.06 behind it tinted RimColor.
    /// Slots are on the ring centre line (radius 225/256 of the half size) at 90 (Top), 270 (Bottom), 135, 45, 225 and 315 degrees;
    /// each motif is drawn at 0.30 of the ring diameter, tinted by its Tint.</summary>
    public sealed class FrameArt
    {
        public readonly string Key;
        public readonly Color32 RingColor;
        public readonly Color32 RimColor;
        public readonly FrameRingStyle Style;
        public readonly int Count;
        public readonly Color32[] StyleColors;
        public readonly FrameMotif[] Motifs;

        public FrameArt(string key, uint ring, uint rim, FrameRingStyle style, int count, uint[] styleColors, FrameMotif[] motifs)
        {
            Key = key;
            RingColor = Rgb(ring);
            RimColor = Rgb(rim);
            Style = style;
            Count = count;
            StyleColors = new Color32[styleColors.Length];
            for (int i = 0; i < styleColors.Length; i++) StyleColors[i] = Rgb(styleColors[i]);
            Motifs = motifs;
        }

        static Color32 Rgb(uint v) => new Color32((byte)(v >> 16), (byte)(v >> 8), (byte)v, 255);

        public static FrameArt Find(string key)
        {
            for (int i = 0; i < All.Count; i++)
                if (All[i].Key == key) return All[i];
            return null;
        }

